<script setup>
import { ref, computed, watch } from 'vue'
import { useRoute } from 'vue-router'
import { apiFetch } from '../services/api.js'
import { usuario, exigirSesion } from '../services/sesion.js'
import IconoForo from '../components/IconoForo.vue'
import CrearComunidad from '../components/CrearComunidad.vue'
import CargaMultimedia from '../components/CargaMultimedia.vue'
import CampoUrlImagen from '../components/CampoUrlImagen.vue'
import MultimediaPublicacion from '../components/MultimediaPublicacion.vue'
const route=useRoute(), items=ref([]), comunidad=ref(null), publicaciones=ref([]), miembros=ref([]), categorias=ref([]),error=ref(''),cargando=ref(false),ocupado=ref(false),modal=ref(false),editar=ref(false),form=ref({}),orden=ref('reciente'),q=ref(''),mas=ref(false),masPosts=ref(false)
const personalizacion=ref({}),iconoCarga=ref(null),portadaCarga=ref(null),nIcono=ref(0),nPortada=ref(0),quitarIcono=ref(false),quitarPortada=ref(false)
const slug=computed(()=>route.params.slug),mias=computed(()=>route.query.mias==='1'),gestor=computed(()=>['propietario','moderador'].includes(comunidad.value?.mi_rol))
const seccionAdmin=ref('informacion'),modoIcono=ref('archivo'),modoPortada=ref('archivo'),aviso=ref('')
const seccionesAdmin=[{id:'informacion',nombre:'Información',icono:'publicaciones'},{id:'apariencia',nombre:'Apariencia',icono:'imagen'},{id:'normas',nombre:'Normas',icono:'publicaciones'},{id:'miembros',nombre:'Miembros',icono:'usuarios'},{id:'solicitudes',nombre:'Solicitudes',icono:'historial'},{id:'moderadores',nombre:'Moderadores',icono:'perfil'},{id:'moderacion',nombre:'Moderación',icono:'configuracion'}]
const miembrosVisibles=computed(()=>miembros.value.filter(m=>seccionAdmin.value==='solicitudes'?!m.aprobado:seccionAdmin.value==='moderadores'?m.aprobado&&['propietario','moderador'].includes(m.rol):m.aprobado))
function abrirAdmin(){editar.value=true;seccionAdmin.value='informacion';modoIcono.value=form.value.icono_url?'url':'archivo';modoPortada.value=form.value.portada_url?'url':'archivo'}
function cerrarAdmin(){if((nIcono.value||nPortada.value)&&!confirm('¿Cerrar la administración y descartar los archivos seleccionados?'))return;editar.value=false;nIcono.value=0;nPortada.value=0;quitarIcono.value=false;quitarPortada.value=false;form.value={nombre:comunidad.value.nombre,descripcion:comunidad.value.descripcion,normas:comunidad.value.normas,icono_url:comunidad.value.icono_url||'',portada_url:comunidad.value.portada_url||''}}
function accionMiembro(m,a){if(a==='expulsar'&&!confirm(m.aprobado?'¿Retirar a este miembro?':'¿Rechazar esta solicitud?'))return;accion(`/comunidades/${comunidad.value.id}/miembros/${m.id_usuario}`,{accion:a})}
function fechaComunidad(fecha){const d=new Date(fecha);return fecha&&!isNaN(d.getTime())?d.toLocaleDateString('es-CO',{year:'numeric',month:'long',day:'numeric'}):''}
let version=0,versionPosts=0
async function cargar(agregar=false){const v=++version;error.value='';cargando.value=true;if(!agregar){items.value=[];comunidad.value=null;publicaciones.value=[];miembros.value=[];personalizacion.value={};nIcono.value=0;nPortada.value=0;quitarIcono.value=false;quitarPortada.value=false;editar.value=false}try{if(slug.value){const c=await apiFetch('foro',`/comunidades/${encodeURIComponent(slug.value)}`);if(v!==version)return;comunidad.value=c;try{const archivos=await apiFetch('foro',`/multimedia/comunidades/${c.id}`);if(v===version)personalizacion.value=archivos}catch(e){if(v===version)error.value=e.message}if(v!==version)return;form.value={nombre:c.nombre,descripcion:c.descripcion,normas:c.normas,icono_url:c.icono_url||'',portada_url:c.portada_url||''};if(c.mi_rol==='propietario'){const m=await apiFetch('foro',`/comunidades/${c.id}/miembros`);if(v===version)miembros.value=m}if(v===version)await cargarPosts()}else{const r=await apiFetch('foro',`/comunidades?${new URLSearchParams({q:q.value,mias:mias.value?'1':'0',offset:String(items.value.length)})}`);if(v!==version)return;items.value.push(...r.slice(0,20));mas.value=r.length>20}}catch(e){if(v===version)error.value=e.message}finally{if(v===version)cargando.value=false}}
async function cargarPosts(agregar=false){const cid=comunidad.value?.id;if(!cid)return;const v=++versionPosts;if(!agregar)publicaciones.value=[];try{const r=await apiFetch('foro',`/preguntas?${new URLSearchParams({comunidad:String(cid),orden:orden.value,limite:'21',offset:String(publicaciones.value.length)})}`);if(v===versionPosts&&comunidad.value?.id===cid){publicaciones.value.push(...r.slice(0,20));masPosts.value=r.length>20}}catch(e){if(v===versionPosts)error.value=e.message}}
async function accion(ruta,body){if(ocupado.value||!exigirSesion('Inicia sesión para participar.'))return;if(editar.value&&(nIcono.value||nPortada.value)&&!confirm('Esta acción recargará la administración. ¿Descartar los archivos seleccionados?'))return;ocupado.value=true;error.value='';try{await apiFetch('foro',ruta,{method:'PUT',body:JSON.stringify(body)});window.dispatchEvent(new Event('comunidades-actualizadas'));await cargar()}catch(e){error.value=e.message}finally{ocupado.value=false}}
async function guardarEdicion(){if(ocupado.value)return;if(form.value.nombre.trim().length<3||!form.value.descripcion.trim()){seccionAdmin.value='informacion';error.value='Completa el nombre y la descripción.';return}for(const [modo,url] of [[modoIcono.value,form.value.icono_url],[modoPortada.value,form.value.portada_url]]){if(modo==='url'&&url){try{const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password)throw new Error()}catch{seccionAdmin.value='apariencia';error.value='Introduce una URL HTTPS válida.';return}}}ocupado.value=true;error.value='';aviso.value='';try{const d={...form.value};if(modoIcono.value==='archivo'&&nIcono.value)d.icono_url='';if(modoPortada.value==='archivo'&&nPortada.value)d.portada_url='';if(modoIcono.value==='archivo'&&nIcono.value)d.icono_archivo=(await iconoCarga.value.preparar())[0];else if(quitarIcono.value||(modoIcono.value==='url'&&d.icono_url&&d.icono_url!==comunidad.value.icono_url))d.icono_archivo=null;if(modoPortada.value==='archivo'&&nPortada.value)d.portada_archivo=(await portadaCarga.value.preparar())[0];else if(quitarPortada.value||(modoPortada.value==='url'&&d.portada_url&&d.portada_url!==comunidad.value.portada_url))d.portada_archivo=null;await apiFetch('foro',`/comunidades/${comunidad.value.id}`,{method:'PUT',body:JSON.stringify(d)});window.dispatchEvent(new Event('comunidades-actualizadas'));await cargar();aviso.value='Cambios guardados.'}catch(e){error.value=e.message}finally{ocupado.value=false}}
async function abrir(){if(!exigirSesion('Inicia sesión para crear una comunidad.'))return;try{categorias.value=await apiFetch('foro','/categorias');modal.value=true}catch(e){error.value=e.message}}
function moderar(p,accionNombre){if(accionNombre==='eliminar'&&!confirm('¿Retirar esta publicación?'))return;accion(`/comunidades/${comunidad.value.id}/preguntas/${p.id}`,{accion:accionNombre,valor:!p[accionNombre]})}
watch([slug,mias,()=>usuario.value?.id],()=>cargar(),{immediate:true});watch(orden,()=>cargarPosts())
</script>
<template>
<main class="pagina pagina-inicio pagina-comunidades">
  <p v-if="error" class="error" role="alert">{{error}} <button class="btn-texto" @click="cargar()">Reintentar</button></p><p v-if="aviso" class="aviso-exito" role="status">{{aviso}}</p><p v-if="cargando" class="foro-estado" role="status">Cargando comunidades…</p>
  <template v-if="!slug">
    <div class="home-intro comunidad-directorio-header"><div><h1>{{mias?'Mis comunidades':'Explorar comunidades'}}</h1><p class="nota-demo">Encuentra espacios de aprendizaje y conversación.</p></div><button class="btn-primario btn-ancho-auto" @click="abrir"><IconoForo nombre="mas"/> Crear comunidad</button></div>
    <div class="directorio-controles"><div class="ux-segmentos"><router-link to="/comunidades" :aria-current="!mias?'page':undefined">Todas</router-link><router-link to="/comunidades?mias=1" :aria-current="mias?'page':undefined">Mis comunidades</router-link></div><form class="directorio-busqueda" @submit.prevent="cargar()"><input v-model="q" maxlength="120" placeholder="Buscar comunidades" aria-label="Buscar comunidades"><button class="btn-secundario">Buscar</button></form></div>
    <p v-if="!cargando&&!items.length&&!error" class="foro-vacio">No hay comunidades que coincidan. {{mias?'Explora las comunidades disponibles.':'Prueba otra búsqueda o crea una comunidad.'}}</p>
    <div class="directorio-rejilla"><article v-for="c in items" :key="c.id" class="tarjeta-pregunta comunidad-directorio-card"><div class="directorio-identidad"><span class="comunidad-icono-placeholder"><img v-if="c.icono_url" :src="c.icono_url" alt="" referrerpolicy="no-referrer" loading="lazy"><IconoForo v-else nombre="usuarios"/></span><div><router-link :to="`/comunidades/${c.slug}`"><h2>{{c.nombre}}</h2></router-link><small>/comunidades/{{c.slug}}</small></div></div><p>{{c.descripcion}}</p><div class="tarjeta-meta">{{c.tematica}} · {{c.miembros}} miembros · {{c.tipo==='publica'?'Pública':'Restringida'}}</div><router-link class="btn-secundario" :to="`/comunidades/${c.slug}`">Ver comunidad</router-link></article></div>
    <button v-if="mas" class="btn-secundario" :disabled="cargando" @click="cargar(true)">Cargar más</button>
  </template>
  <template v-else-if="comunidad">
    <section class="panel-lateral comunidad-cabecera">
      <div class="comunidad-banner"><img v-if="personalizacion.portada||comunidad.portada_url" :src="personalizacion.portada||comunidad.portada_url" alt="" referrerpolicy="no-referrer" class="comunidad-portada"></div>
      <div class="comunidad-cabecera-interior"><div class="comunidad-identidad"><span class="comunidad-avatar"><img v-if="personalizacion.icono||comunidad.icono_url" :src="personalizacion.icono||comunidad.icono_url" alt="" referrerpolicy="no-referrer"><IconoForo v-else nombre="usuarios"/></span><div><h1>{{comunidad.nombre}}</h1><p class="tarjeta-meta">/comunidades/{{comunidad.slug}} · {{comunidad.miembros}} miembros</p><span class="insignia">{{comunidad.tematica}}</span> <span class="tarjeta-meta">{{comunidad.tipo==='publica'?'Pública':'Restringida'}}</span></div></div>
      <div class="comunidad-acciones"><button v-if="comunidad.mi_rol!=='propietario'" class="btn-secundario" :disabled="ocupado" @click="accion(`/comunidades/${comunidad.id}/membresia`,{unirse:!comunidad.mi_rol&&!comunidad.pendiente})">{{comunidad.mi_rol?'Abandonar':comunidad.pendiente?'Cancelar solicitud':comunidad.tipo==='restringida'?'Solicitar ingreso':'Unirme'}}</button><router-link v-if="comunidad.tipo==='publica'||comunidad.mi_rol" class="btn-primario btn-ancho-auto" :to="{path:'/',query:{crear:'1',comunidad:String(comunidad.id),categoria:String(comunidad.id_categoria),slug:comunidad.slug}}"><IconoForo nombre="mas"/> Publicar</router-link><details class="comunidad-menu"><summary class="btn-secundario" aria-label="Más acciones">···</summary><div class="comunidad-menu-contenido"><router-link :to="{path:'/',query:{comunidad:String(comunidad.id),slug:comunidad.slug}}">Ver feed e interactuar</router-link><button v-if="comunidad.mi_rol==='propietario'" class="btn-texto" @click="abrirAdmin">Administrar comunidad</button></div></details></div></div>
    </section>
    <section v-if="editar&&comunidad.mi_rol==='propietario'" class="panel-lateral comunidad-admin"><div class="admin-cabecera"><div><h2>Administrar comunidad</h2><p class="nota-demo">Gestiona la identidad, miembros y normas.</p></div><button type="button" class="btn-icono" aria-label="Cerrar administración" :disabled="ocupado" @click="cerrarAdmin"><IconoForo nombre="cerrar"/></button></div><div class="comunidad-admin-grid"><nav aria-label="Administración de comunidad" class="admin-comunidad-nav"><button v-for="t in seccionesAdmin" :key="t.id" type="button" :aria-pressed="seccionAdmin===t.id" :disabled="ocupado" @click="seccionAdmin=t.id"><IconoForo :nombre="t.icono"/>{{t.nombre}}</button></nav><div class="admin-comunidad-contenido">
      <form v-show="['informacion','apariencia','normas'].includes(seccionAdmin)" @submit.prevent="guardarEdicion" novalidate>
        <section v-show="seccionAdmin==='informacion'" class="ux-campos"><h3>Información de la comunidad</h3><label>Nombre<input v-model="form.nombre" required maxlength="60"></label><label>Descripción<textarea v-model="form.descripcion" required maxlength="500" rows="4"></textarea></label></section>
        <section v-show="seccionAdmin==='apariencia'" class="ux-campos"><h3>Apariencia</h3><div class="comunidad-doble"><div class="ux-campos"><h4>Icono</h4><div class="ux-segmentos" role="group" aria-label="Origen del icono"><button v-for="m in ['archivo','url']" :key="m" type="button" :aria-pressed="modoIcono===m" :disabled="ocupado" @click="modoIcono=m">{{m==='archivo'?'Dispositivo':'URL HTTPS'}}</button></div><CargaMultimedia v-show="modoIcono==='archivo'" ref="iconoCarga" tipo="multimedia" uso="icono" :bloqueado="ocupado" @cambio="nIcono=$event"/><CampoUrlImagen v-if="modoIcono==='url'" v-model="form.icono_url" etiqueta="Icono HTTPS" :bloqueado="ocupado"/><label v-if="personalizacion.icono" class="ux-check"><input type="checkbox" v-model="quitarIcono"> Quitar icono cargado</label></div><div class="ux-campos"><h4>Portada</h4><div class="ux-segmentos" role="group" aria-label="Origen de la portada"><button v-for="m in ['archivo','url']" :key="m" type="button" :aria-pressed="modoPortada===m" :disabled="ocupado" @click="modoPortada=m">{{m==='archivo'?'Dispositivo':'URL HTTPS'}}</button></div><CargaMultimedia v-show="modoPortada==='archivo'" ref="portadaCarga" tipo="multimedia" uso="portada" :bloqueado="ocupado" @cambio="nPortada=$event"/><CampoUrlImagen v-if="modoPortada==='url'" v-model="form.portada_url" etiqueta="Portada HTTPS" :bloqueado="ocupado"/><label v-if="personalizacion.portada" class="ux-check"><input type="checkbox" v-model="quitarPortada"> Quitar portada cargada</label></div></div></section>
        <section v-show="seccionAdmin==='normas'" class="ux-campos"><h3>Normas de convivencia</h3><label>Normas<textarea v-model="form.normas" maxlength="2000" rows="6"></textarea></label></section>
        <div class="admin-guardar"><button class="btn-primario btn-ancho-auto" :disabled="ocupado">{{ocupado?'Guardando…':'Guardar cambios'}}</button></div>
      </form>
      <section v-if="['miembros','solicitudes','moderadores'].includes(seccionAdmin)" class="ux-campos"><h3>{{seccionesAdmin.find(t=>t.id===seccionAdmin)?.nombre}}</h3><p v-if="!miembrosVisibles.length" class="foro-vacio">No hay resultados en esta sección.</p><article v-for="m in miembrosVisibles" :key="m.id_usuario" class="admin-miembro"><span class="comunidad-icono-placeholder"><IconoForo nombre="perfil"/></span><div><router-link :to="`/usuarios/${m.id_usuario}`">{{m.nombre_apellido}}</router-link><small>{{m.aprobado?m.rol:'Pendiente'}}</small></div><div v-if="m.rol!=='propietario'" class="tarjeta-acciones"><button v-for="a in (m.aprobado?[m.rol==='moderador'?'miembro':'moderador','expulsar']:['aprobar','expulsar'])" :key="a" class="btn-texto" :class="{'accion-delicada':a==='expulsar'}" :disabled="ocupado" @click="accionMiembro(m,a)">{{a==='moderador'?'Hacer moderador':a==='miembro'?'Quitar moderador':a==='aprobar'?'Aprobar':m.aprobado?'Retirar':'Rechazar'}}</button></div></article></section>
      <section v-if="seccionAdmin==='moderacion'" class="ux-campos"><h3>Moderación de publicaciones</h3><p>Fija, cierra o retira publicaciones utilizando sus acciones de moderación en el feed de esta comunidad.</p><button type="button" class="btn-secundario" @click="cerrarAdmin">Ir al feed</button></section>
    </div></div></section>
    <div class="comunidad-rejilla-principal"><section class="comunidad-feed"><div class="feed-toolbar"><h2>Publicaciones</h2><select v-model="orden" aria-label="Orden"><option value="reciente">Recientes</option><option value="popular">Popular</option><option value="tendencias">Tendencias</option></select></div><p v-if="!cargando&&!publicaciones.length&&!error" class="foro-vacio">Aún no hay publicaciones.</p><div class="feed-lista"><article v-for="p in publicaciones" :key="p.id" class="tarjeta-pregunta"><p class="tarjeta-meta">{{p.nombre_autor}} · {{p.total_votos}} votos · {{p.cantidad_respuestas}} respuestas</p><h2><router-link :to="`/preguntas/${p.id}`">{{p.titulo}}</router-link></h2><p class="tarjeta-extracto">{{p.contenido}}</p><img v-if="p.tipo==='imagen'&&p.recurso_url" :src="p.recurso_url" alt="Imagen publicada" loading="lazy" referrerpolicy="no-referrer" class="feed-imagen"><MultimediaPublicacion v-if="['multimedia','video'].includes(p.tipo)" :id="p.id"/><div class="tarjeta-acciones"><router-link class="btn-texto" :to="`/preguntas/${p.id}`">Ver conversación</router-link><template v-if="gestor"><button v-for="a in ['fijada','cerrada','eliminar']" :key="a" class="btn-texto" :class="{'accion-delicada':a==='eliminar'}" :disabled="ocupado" @click="moderar(p,a)">{{a==='fijada'?(p.fijada?'Desfijar':'Fijar'):a==='cerrada'?(p.cerrada?'Reabrir':'Cerrar'):'Retirar'}}</button></template></div></article></div><button v-if="masPosts" class="btn-secundario" @click="cargarPosts(true)">Cargar más</button></section>
    <aside class="comunidad-aside"><section class="panel-lateral"><h2>Acerca de la comunidad</h2><p>{{comunidad.descripcion}}</p><dl class="comunidad-datos"><div><dt>Miembros</dt><dd>{{comunidad.miembros}}</dd></div><div><dt>Temática</dt><dd>{{comunidad.tematica}}</dd></div></dl><p v-if="fechaComunidad(comunidad.fecha_creacion)" class="nota-demo">Creada el {{fechaComunidad(comunidad.fecha_creacion)}}</p></section><section class="panel-lateral"><h2>Normas</h2><p class="comunidad-normas">{{comunidad.normas||'Aún no hay normas adicionales.'}}</p></section><section class="panel-lateral"><h2>Moderadores</h2><div v-for="m in comunidad.moderadores" :key="m.id" class="moderador-fila"><IconoForo nombre="perfil"/><div><router-link :to="`/usuarios/${m.id}`">{{m.nombre_apellido}}</router-link><small>{{m.rol}}</small></div></div></section></aside></div>
  </template>
  <CrearComunidad v-if="modal" :categorias="categorias" @cerrar="modal=false" @creada="cargar()"/>
</main>
</template>
